#!/usr/bin/env python3
import numpy as np
import os

class calcat():
    def __init__(self, jobname, dynamics, Energy, dynstate, ionstate, method=['gaussian', 'readenergy.txt'], tempxyz='neut_stru.xyz', force='force', vdestates = ['ani', 'vde.out'], diff='diff'):
        # jobname   = [rhombus, Ag4]               files
        # dynamics  = dynamics              dynamics
        # Energy    = Energy                Energy
        # dynstate  = neut                  dynamic state
        # ionstate  = cat                   ionized state
        # force     = force                 output files
        # method    = ['gaussian', 'readenergy.txt']    method, read energy
        # tempxyz   = 'neut_stru.xyz'       temp .xyz file from neut init geometry
        # vdestates = ['ani', '']           states for vde first, second format .com file with jobname
        # diff      = diff                  diff of neutral and cation

        if method[0] == 'guassian' or method[0] == 'qchem':
            from gaussian_parser import Checkpoint
        elif method[0] == 'orca':
            import orca_parser as orp
        
        self.force = force 
        self.jobname = jobname
        self.tempcatxyz = tempxyz
        self.method = method
        self.Enname = Energy
        self.vdestates = vdestates
        self.dynE = '{}_{}.out'.format(self.jobname[0], self.Enname) 
        self.ionE = '{}{}_{}.out'.format(self.jobname[0], ionstate, self.Enname)
        self.com = '{}{}'.format(self.jobname[1], ionstate)
        self.fchk = '{}{}'.format(force, ionstate)
        self.cordf = '{}_{}.xyz'.format(self.jobname[0], dynamics)
        self.intraj, self.atoms = self.gettraj(self.cordf) # load previous trajectory
        self.getens = self.whichenread(self.method, self.ionE)
        self.timeax = np.loadtxt(self.dynE, delimiter='\t', skiprows=1)[:, 0]
        self.ediff = '{}_{}.out'.format(diff, self.Enname)

    def startrecalc(self):
        self.recalc(self.tempcatxyz, self.atoms, self.intraj)

    def recalc(self, xyzf, atoms, coordinates):
        time = 0
        #_ = self.whichenread(self.method, self.ionE)
        for i, coords in enumerate(coordinates): #write .xyz file
            with open(xyzf, 'w') as f:
                num_atoms = len(atoms)
                if self.method[0] != 'gaussian':
                    f.write(str(num_atoms) + '\n\n')
                for j in range(num_atoms):
                    atom_line = '{}\t{}\t{}\t{}\n'.format(atoms[j], coords[j][0], coords[j][1], coords[j][2])
                    f.write(atom_line)
            os.system('g16 {0}.com {0}.log'.format(self.com))   # run cat calc
            os.system('formchk {0}.chk {0}.fchk'.format(self.fchk)) #formchk forcecat.chk forcecat.
            os.system('date >> time.txt')
            self.write_energy(self.timeax[i], '{}.fchk'.format(self.fchk), self.ionE)
            time += 1
        self.neutiondiff()

    def gettraj(self, xyzname):
        lines = self.get_line_count(xyzname)
        with open(xyzname, 'r') as f: # init read trajectory
            num_atoms = int(f.readline())
            f.readline()
            coordinates = np.zeros((num_atoms, 3))
            atl = []
            for i in range(num_atoms):
                line = f.readline().split()
                atom_symbol, x, y, z = line[0], float(line[1]), float(line[2]), float(line[3])
                atl.append(atom_symbol)
                coordinates[i, :] = [x, y, z]
            col = [coordinates]
            if lines > num_atoms+2: # read all the other coordinates
                for i in range(int(lines/(num_atoms+2)-1)):
                    _ = f.readline()
                    _ = f.readline()
                    for i in range(num_atoms):
                        line = f.readline().split()
                        atom_symbol, x, y, z = line[0], float(line[1]), float(line[2]), float(line[3])
                        coordinates[i, :] = [x, y, z]
                    col.append(coordinates)
        return col, atl

    def get_line_count(self, file_path):
        with open(file_path, 'r') as f:
            lc = sum(1 for i in f)
        return lc

    def whichenread(self, methode, jname): # init the _Energy.out file with its col-axis 
            with open(methode[1], 'r') as f:
                data = f.readlines()
            read = False
            i = 1
            readen = []
            quit = False
            while i < len(data) and quit == False:
                if methode[0] in data[i] and read == False:
                    read = True
                elif read == True:
                    if data[i] == '\n' or '#' in data[i]:
                        quit = True
                    else:
                        readen.append(data[i].split('\n')[0])
                i += 1
            with open(jname, 'w+') as f:
                f.write('time[fs]' + '\t')
                for i in readen:
                    f.write(i + '\t')
                f.write('\n')
            return readen
    
    def get_Energy(self, filen, search): # split file to get the requested energies
        with open(filen) as f:
            a = f.readlines()
            for i in a:
                if search in i:
                    return float(i.split(' ')[-1])
    
    def write_energy(self, time, rfile, wfile): # write the requested energies into a row
        if self.method[0] == 'gaussian':
            wrst = '{}'.format(time)
            for i in self.getens:
                wrst = '{}\t{}'.format(wrst, self.get_Energy(rfile, i))
            with open(wfile, 'a') as f:
                f.write('{}\n'.format(wrst))
        
    def load_matrix(self, file_path): # load energy matrix
        matrix = np.loadtxt(file_path, delimiter='\t', skiprows=1)
        with open(file_path, 'r') as file:
            first_row = file.readline().strip().split('\t')
            header_array = np.array(first_row)
        return header_array, matrix

    def calcmatrixdiff(self, Eneut, Ecat, diffname, time): # calculate difference between both dynamic matrices 
        lines, Eneut = self.load_matrix(Eneut)
        _, Ecat = self.load_matrix(Ecat)
        diff = np.subtract(Eneut[:, 1:], Ecat[:, 1:])
        with open(diffname, 'w') as f:
            for i in lines:
                f.write(i)
                f.write('\t')
            f.write('\n')
            for i in range(len(diff)):
                row = '\t'.join(map(str, diff[i]))
                f.write('{}\t{}\n'.format(time[i], row))

    def neutiondiff(self):
        self.calcmatrixdiff(self.dynE, self.ionE, self.ediff, self.timeax)

    def anic(self, dyn, free=0):
        with open(dyn) as f:
            natoms = int(f.readline())
            f.readline() # emthy line
            coord = f.readlines()
            with open('coord.xyz', 'w') as g:
                for j in range(natoms):
                    g.write(coord[j+free])

    def getvde(self):
        self.anic(self.cordf) # init for Anion calc
        os.system('g16 {0}{1}.com {0}{1}.log'.format(self.jobname[1], self.vdestates[0]))
        os.system('formchk {0}{1}.chk {0}{1}.fchk'.format(self.force, self.vdestates[0]))
        E_low = []
        for i in self.getens:
            E_low.append(self.get_Energy('{0}{1}.fchk'.format(self.force, self.vdestates[0]), i))
        E_high = self.load_matrix(self.dynE)[1][0, 1:] 
        diff = np.subtract(E_low, E_high)
        wrst = 'time[fs]\t'
        for i in self.getens:
            wrst = '{}\t{}'.format(wrst, i)
        wrst = '{}\n{}'.format(wrst, self.timeax[0])
        for i in diff:
            wrst = '{}\t{}'.format(wrst, i)
        with open(self.vdestates[1], 'w') as f:
            f.write(wrst)
       
def get_in(ending):
    files = os.listdir()
    for i in files:
        if ending in i:
            return i
